// Trafik lambası: kırmızı -> kırmızı+sarı -> yeşil -> sarı
const int KIRMIZI = 8;
const int SARI = 9;
const int YESIL = 10;

void setup() {
  pinMode(KIRMIZI, OUTPUT);
  pinMode(SARI, OUTPUT);
  pinMode(YESIL, OUTPUT);
}

void loop() {
  digitalWrite(KIRMIZI, HIGH);          // dur
  delay(5000);

  digitalWrite(SARI, HIGH);             // kırmızı + sarı: hazırlan
  delay(1500);

  digitalWrite(KIRMIZI, LOW);
  digitalWrite(SARI, LOW);
  digitalWrite(YESIL, HIGH);            // geç
  delay(5000);

  digitalWrite(YESIL, LOW);
  digitalWrite(SARI, HIGH);             // yavaşla
  delay(2000);
  digitalWrite(SARI, LOW);
}
